<script setup lang="ts">
import {computed,ref,watch} from 'vue'
import {useRoute} from 'vue-router'
import {useWorkforce} from '../context'
import {useWorkforceText} from '../text'
import {usePositionText} from '../positionText'
import {usePhaseText} from '../phaseText'
import {useDocumentExpiryText} from '../documentExpiry'
import {useDocumentText} from '../documentText'
import {useStatutoryText} from '../statutoryPolicy'
import {useWorkModeText} from '../workMode'
const {w}=useWorkModeText()
import {attendanceSettingsText as a} from '../attendanceSettingsText'
import {explanationText} from '../reviewExplanations'
import PayrollSettingsLinks from '../components/PayrollSettingsLinks.vue'
const {home,store,payrollHome,payrollFailure,refresh}=useWorkforce(),{t}=useWorkforceText(),{j}=usePositionText(),{p,english}=usePhaseText()
const route=useRoute(),selectedCompany=computed(()=>payrollHome?.value?.companies.find(c=>c.id===String(route.query.companyId||home.value?.stores?.find(s=>s.id===store.value)?.companyId||''))?.id)
const requestedStep=Number(route.query.step)
const initialStep=()=>[1,2,3,4].includes(requestedStep)&&(home.value?.employeeManage||requestedStep>=3)?requestedStep:(home.value?.employeeManage?1:3)
const activeStep=ref(initialStep())
const steps=computed(()=>[...(home.value?.employeeManage?[{id:1,title:english()?'Organisation':'组织与权限'},{id:2,title:english()?'Attendance':'打卡与工时'}]:[]),{id:3,title:english()?'Pay setup':'薪资方案'},{id:4,title:english()?'Monthly payroll':'每月计薪'}])
watch(()=>home.value?.employeeManage,()=>{activeStep.value=initialStep()})
const currentIndex=computed(()=>steps.value.findIndex(s=>s.id===activeStep.value))
const {d}=useDocumentText(),{x}=useDocumentExpiryText(),{s}=useStatutoryText()
</script>
<template><section v-if="home?.employeeManage||payrollHome?.companies.length||payrollFailure" class="wf-panel wf-management-page"><header class="wf-management-header"><h2>{{j('management')}}</h2></header>
<p class="wf-muted">{{english()?'First time? Follow these steps. Returning users can go straight to the setting they need. This guide does not change or save settings.':'首次使用，按顺序设置；已有配置可直接选择需要调整的步骤。切换步骤不会修改或保存设置。'}}</p>
<nav class="setup-steps" :aria-label="english()?'Setup steps':'设置步骤'"><button v-for="(step,index) in steps" :key="step.id" :aria-current="activeStep===step.id?'step':undefined" :aria-controls="'setup-step-'+step.id" @click="activeStep=step.id"><span>{{index+1}}</span>{{step.title}}</button></nav>
<section v-if="home?.employeeManage" v-show="activeStep===1" id="setup-step-1" class="wf-section"><h3>{{english()?'Confirm who works here and who can configure payroll':'先确定公司、岗位和操作权限'}}</h3><p class="wf-muted">{{english()?'Head office maintains companies, positions and access. Store managers can use existing settings.':'总部先维护发薪公司、岗位，再分配管理员权限；门店管理员使用已有配置。'}}</p><nav v-if="home.headOffice" class="wf-management-links" :aria-label="a('peopleGroup',english())"><RouterLink :to="`/stores/${store}/workforce/companies`"><strong>{{t('companies')}}</strong><span>{{j('companyHint')}}</span></RouterLink><RouterLink :to="`/stores/${store}/workforce/positions`"><strong>{{j('title')}}</strong><span>{{j('positionHint')}}</span></RouterLink><RouterLink :to="`/stores/${store}/workforce/administrators`"><strong>{{j('authorization')}}</strong><span>{{j('authorizationHint')}}</span></RouterLink></nav><p v-else class="wf-muted">{{english()?'Company, position and access settings are maintained by head office. Continue with store attendance.':'公司、岗位及权限由总部维护，可继续设置门店考勤。'}}</p><nav class="wf-management-links"><RouterLink v-if="home?.headOffice&&home.employeeManage" :to="`/stores/${store}/workforce/compliance-policies`"><strong>{{english()?'Contract & leave policies':'合同与假期政策'}}</strong><span>{{english()?'Review official sources, publish, then adopt employee contracts and balances.':'核对官方依据并发布，再确认员工合同及额度。'}}</span></RouterLink><RouterLink :to="`/stores/${store}/workforce/employees`"><strong>{{english()?'Employee contracts & leave':'员工合同与假期额度'}}</strong><span>{{english()?'Choose an employee → Contract & leave.':'选择员工后，进入合同与假期，对账启用。'}}</span></RouterLink></nav><details class="setup-more"><summary>{{english()?'Documents and expiry reminders':'证件与到期提醒（按需维护）'}}</summary><nav class="wf-management-links" :aria-label="english()?'Documents':'证件设置'"><RouterLink :to="`/stores/${store}/workforce/document-expiries`"><strong>{{x('title')}}</strong><span>{{x('hint')}}</span></RouterLink><template v-if="home.headOffice"><RouterLink :to="`/stores/${store}/workforce/document-types`"><strong>{{d('types')}}</strong><span>{{d('typeHint')}}</span></RouterLink></template></nav></details></section>
<section v-if="home?.employeeManage" v-show="activeStep===2" id="setup-step-2" class="wf-section"><h3>{{english()?'Prepare clocking and approved hours':'让打卡记录能准确核成工时'}}</h3><p class="wf-muted">{{english()?'Set clock locations and break rules, then shifts and holidays. Check and approve hours before payroll.':'先设置打卡定位点、休息与考勤规则，再维护班次及假期；每月核准工时后再计薪。'}}</p><nav class="wf-management-links" :aria-label="a('attendanceGroup',english())"><RouterLink :to="`/stores/${store}/workforce/clock-site`"><strong>{{w('site')}}</strong><span>{{w('siteHint')}}</span></RouterLink>
<RouterLink :to="`/stores/${store}/workforce/attendance-rules`"><strong>{{a('rules',english())}}</strong><span>{{english()?'Maintain reusable break and attendance rules.':'维护班次可选用的休息及异常判定规则。'}}</span></RouterLink><RouterLink :to="`/stores/${store}/workforce/shifts`"><strong>{{p('shifts')}}</strong><span>{{j('shiftHint')}}</span></RouterLink>
</nav><details class="setup-more"><summary>{{english()?'Holidays, calendar and decision explanations':'假期、日历与判定说明（按需维护）'}}</summary><nav class="wf-management-links" :aria-label="english()?'Additional attendance settings':'其他考勤设置'"><RouterLink :to="`/stores/${store}/workforce/leave-types`"><strong>{{a('leave',english())}}</strong><span>{{a('leaveHint',english())}}</span></RouterLink>
<RouterLink :to="`/stores/${store}/workforce/public-holidays`"><strong>{{a('annual',english())}}</strong><span>{{a('annualHint',english())}}</span></RouterLink>
<RouterLink :to="`/stores/${store}/workforce/calendar`"><strong>{{a('calendar',english())}}</strong><span>{{a('calendarHint',english())}}</span></RouterLink>

<RouterLink :to="`/stores/${store}/workforce/review-explanations`"><strong>{{explanationText('title',english())}}</strong><span>{{explanationText('hint',english())}}</span></RouterLink></nav></details></section>
<section v-show="activeStep===3" id="setup-step-3" class="wf-section"><h3>{{english()?'Set default pay, then confirm employee differences':'先定薪资标准，再确认员工个人差异'}}</h3><p class="wf-muted">{{english()?'Use published templates where available; verify statutory rules, then maintain employee pay and effective dates.':'优先使用已发布的门店模板；总部核对法定规则，再维护员工薪资及生效日期。月薪、时薪和个人差异以员工有效方案为准。'}}</p><nav class="wf-management-links" :aria-label="a('payrollGroup',english())"><template v-if="home?.employeeManage"><RouterLink :to="`/stores/${store}/workforce/pay-template-library`"><strong>{{english()?'Store pay template library':'门店工资模板库'}}</strong><span>{{english()?'Preview and enable fixed published templates.':'预览并显式启用总部发布的固定版本模板。'}}</span></RouterLink></template><RouterLink v-if="home?.headOffice&&home?.employeeManage" :to="`/stores/${store}/workforce/statutory-policies`"><strong>{{s('title')}}</strong><span>{{s('entryHint')}}</span></RouterLink><RouterLink v-if="payrollHome?.companies.length" :to="{path:`/stores/${store}/workforce/position-pay-plans`,query:selectedCompany?{companyId:selectedCompany}:undefined}"><strong>{{english()?'Position pay standards':'岗位薪资标准'}}</strong><span>{{english()?'Set monthly or hourly defaults and allowances before confirming employee pay.':'按岗位设置月薪或时薪及津贴，再核对员工个人薪资。'}}</span></RouterLink><PayrollSettingsLinks v-if="payrollHome?.companies.length" :base="`/stores/${store}/workforce`" :company-id="selectedCompany"/><RouterLink v-if="home?.employeeManage&&!payrollHome?.companies.length" :to="`/stores/${store}/workforce/pay-change-requests`"><strong>{{english()?'Store template change requests':'门店模板变更申请'}}</strong><span>{{english()?'Submit store template changes for approval; personal salary access is separately granted.':'提交本店模板变更并跟踪审批；个人工资仍需单独授权。'}}</span></RouterLink></nav></section>
<section v-show="activeStep===4" id="setup-step-4" class="wf-section"><h3>{{english()?'Ready for monthly payroll':'设置完成后，开始每月计薪'}}</h3><p>{{english()?'Check clock records → approve hours → calculate this month → review exceptions and personal details → confirm → publish payslips.':'核对打卡 → 核准工时 → 本月测算 → 总表检查异常与个人明细 → 正式确认 → 发布工资单。'}}</p><p class="wf-muted">{{english()?'Review effective employee pay plans before calculating. Completed payroll is not changed by this setup guide.':'测算前确认员工薪资方案已生效；本设置引导不会改写已确认的历史工资。'}}</p><nav class="wf-management-links" :aria-label="english()?'Start payroll':'开始计薪'"><RouterLink v-if="home?.employeeManage" :to="`/stores/${store}/workforce/approvals`"><strong>{{english()?'Approve hours':'核准工时'}}</strong><span>{{english()?'Resolve missing punches and attendance exceptions first.':'先处理漏打卡及出勤异常，确认可计薪工时。'}}</span></RouterLink><RouterLink v-if="payrollHome?.companies.length" :to="{path:`/stores/${store}/workforce/payroll`,query:selectedCompany?{companyId:selectedCompany}:undefined}"><strong>{{english()?'Open payroll':'进入工资工作台'}}</strong><span>{{english()?'Calculate, review, confirm and publish.':'按引导完成测算、检查、确认与发布。'}}</span></RouterLink></nav></section>
<footer class="wf-form-actions"><button v-if="currentIndex>0" @click="activeStep=steps[currentIndex-1].id">{{english()?'Previous step':'上一步'}}</button><button v-if="currentIndex<steps.length-1" class="primary" @click="activeStep=steps[currentIndex+1].id">{{english()?'Next: ':'下一步：'}}{{steps[currentIndex+1].title}}</button></footer>
<p v-if="payrollFailure" role="alert" class="wf-error">{{payrollFailure}} <button @click="refresh">{{t('refresh')}}</button></p></section><p v-else role="alert">{{t('noAccess')}}</p></template>

<style scoped>
.setup-more{margin-top:18px}.setup-more summary{cursor:pointer;padding:10px 0;font-weight:600}.setup-steps{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:8px;margin:18px 0}.setup-steps button{display:flex;align-items:center;gap:8px;text-align:left;min-width:0;white-space:normal;padding:12px}.setup-steps span{display:inline-flex;align-items:center;justify-content:center;border-radius:50%;background:#edf2f7;min-width:24px;height:24px}.setup-steps [aria-current="step"]{border-color:var(--wf-primary,#275d7c);background:#edf5fa;font-weight:700}.setup-steps [aria-current="step"] span{background:#275d7c;color:white}.setup-steps button:focus-visible{outline:2px solid #275d7c;outline-offset:2px}@media(max-width:700px){.setup-steps{grid-template-columns:repeat(2,minmax(0,1fr))}}
</style>
